import {getSessionContext} from "@/lib/auth";import {supplierComparisonAction} from "@/lib/actions/supplier-comparisons";
import {PageHeader} from "@/components/layout/page-header";import {SupplierComparisonPanel} from "@/components/modules/vendors/supplier-comparisons";
export default async function SupplierComparisonPage({params,searchParams}:{params:Promise<{id:string}>;searchParams:Promise<Record<string,string|string[]|undefined>>}){const {id}=await params,query=await searchParams,raw=Number(query.page??1),page=Number.isSafeInteger(raw)&&raw>0?Math.min(raw,10000):1,context=await getSessionContext();const result=await supplierComparisonAction({command:"request.load",request_id:id,page});return <div className="space-y-5"><PageHeader title="Compare supplier offers" description="Review landed costs and the commercial conditions that remain different."/>{result.success&&result.kind==="comparison"?<SupplierComparisonPanel key={`${context.companyId}:${context.userId}:${context.role}:${id}`} initial={result.data}/>:<p role="alert">{result.success?"Unavailable":result.error}</p>}</div>;}
